import {FIELDS,validateClimate,sampleClimate,climateCanvas,routeEnvironment,timeBudget,ageDays} from './environment.js';
import {distance} from './route.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(v,d=1)=>Number.isFinite(v)?v.toFixed(d):'No data';
const link=(url,title)=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(title)} ↗</a>`;
const metric=(title,value)=>`<div><dt>${esc(title)}</dt><dd>${esc(value)}</dd></div>`;
export function createEnvironmentUI(callbacks){
 let model=null,observations=null,point=null,start=null,end=null,epoch=0,selectedField='airTemperatureK',mapped=false,report=null,remIndex=0;
 const cache=new Map();
 const panel=$('environment-pane');
 panel.innerHTML=`<div class="eyebrow">ENVIRONMENT / SCIENCE CONTEXT</div><p class="env-warning">Planning research, not EVA clearance. No global live-weather feed is connected.</p>
 <label class="env-label">SEASON · SOLAR LONGITUDE Ls<select id="climate-season"><option value="0">0° · northern spring</option><option value="90">90° · northern summer</option><option value="180">180° · northern autumn</option><option value="270">270° · northern winter</option></select></label>
 <label class="env-label">LOCAL SOLAR TIME<select id="climate-hour"><option value="14">14:00 · afternoon</option><option value="2">02:00 · night</option></select></label>
 <p class="env-note">Same local hour at each longitude, not a simultaneous snapshot. Climatology / average solar activity; not a forecast for today.</p>
 <label class="env-label">CLIMATE MAP<select id="climate-field">${Object.entries(FIELDS).map(([k,f])=>`<option value="${k}">${f.label}</option>`).join('')}</select></label><button id="show-climate" class="env-button" disabled>Show model on map</button>
 <div id="climate-legend"><div class="climate-gradient"></div><div id="climate-scale"></div></div><p id="climate-status" role="status">Loading climate snapshot…</p><button id="climate-retry" class="env-button" hidden>Retry climate data</button>
 <div id="point-environment"><p>Click the map to inspect a location.</p></div><button id="point-export" class="env-button" disabled>Export point report JSON ↓</button>
 <details open class="env-section"><summary>Mission observations · archive</summary><p class="env-note">These are local measurements, not weather at an arbitrary selected point. Pins use landing-site references, not current rover positions.</p><div id="station-observations">Loading archived measurements…</div></details>
 <details class="env-section"><summary>Life-support data & remaining gaps</summary><p>Atmosphere: CO₂-dominated and unbreathable. A pressurised habitat/suit, supplied oxygen and CO₂ removal are required. The map does not know your equipment limits.</p>
 <p>${link('https://science.nasa.gov/mars/facts/','NASA Mars environment')}</p>
 <p><strong>Ionising radiation:</strong> RAD measured an average <strong>0.67 mSv/day</strong> at Gale during August 2012–June 2013. This historical benchmark is not today’s dose or a prediction of solar events.</p><p>${link('https://www.nasa.gov/news-release/nasa-rover-results-include-first-age-measurement-on-mars-and-help-for-human-exploration/','NASA / Curiosity RAD')}</p>
 <p><strong>Water:</strong> SWIM identifies evidence consistent with subsurface ice. Accessible water quantity, depth and extraction capability are not verified at the selected point.</p><p>${link('https://swim.psi.edu/','SWIM water-ice resources')}</p>
 <p><strong>Still unknown:</strong> local slopes and obstacles, current dust storms, solar particle events, shelter, communications and actual consumable reserves. RGB imagery is not a calibrated terrain model.</p></details>
 <details class="env-section"><summary>Sources & resolution</summary><p id="climate-source"></p><p>Global grid: 64 × 48 samples, about 5.7° × 3.8° (hundreds of kilometres). Nearest-cell sampling; no local detail is invented when zooming. ASCII longitude labels have up to 1° rounding/truncation uncertainty.</p><p>MCD 6.2 © LMD/OU/IAA/ESA/CNES. Air temperature and wind: 2 m above ground. Dust: monthly mean visible column optical depth, not wind-blown surface dust or a storm warning.</p></details>`;
 $('route-environment').innerHTML=`<div class="eyebrow">ENVIRONMENT & TIME BUDGET</div><p class="env-note">Uses the seasonal model selected in Environment. Enter your own planning assumptions; these are not validated spacesuit specifications.</p><label class="env-label">TRAVEL SPEED (km/h)<input id="eva-speed" type="number" min="0.1" max="100" step="0.1" value="3"></label><label class="env-label">ASSUMED AUTONOMY (hours)<input id="eva-autonomy" type="number" min="0.5" max="1000" step="0.5" value="8"></label><label class="env-label">RESERVE (%)<input id="eva-reserve" type="number" min="0" max="99" value="30"></label><label class="env-label">SCIENCE / REST STOPS (hours)<input id="eva-stops" type="number" min="0" max="1000" step="0.25" value="0"></label><label class="grid-toggle"><input id="eva-return" type="checkbox" checked> Include return along the same path</label><div id="route-climate-result" role="status">Set a start and destination.</div><button id="route-climate-export" class="env-button" disabled>Export environment / time report ↓</button>`;
 const tabs=[...document.querySelectorAll('[data-pane]')];
 function openTab(tab){for(const b of tabs){const active=b===tab;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;$(b.dataset.pane+'-pane').hidden=!active;}}
 tabs.forEach((b,i)=>{b.tabIndex=i? -1:0;b.onclick=()=>openTab(b);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;openTab(tabs[n]);tabs[n].focus();}};});
 function legend(){const f=FIELDS[selectedField];$('climate-scale').textContent=`${f.range[0]} — ${f.range[1]} ${f.unit} · MODEL`;}
 function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function draw(){if(!model)return;callbacks.map(climateCanvas(model,selectedField));mapped=true;}
 function pointReport(){if(!model||!point)return null;return {selectedPoint:point,model:sampleClimate(model,point.lat,point.lon),source:model.source,retrievedAt:model.retrievedAt,grid:model.spatialResolution,coordinateUncertaintyDegrees:model.coordinateUncertaintyDegrees,scenario:model.scenario,observationsAreNotAtSelectedPoint:true,operationalSafety:'unknown'};}
 function renderPoint(){
  $('point-export').disabled=!(model&&point);if(!point)return;if(!model){$('point-environment').textContent='Model data unavailable for this point.';return;}
  const s=sampleClimate(model,point.lat,point.lon);
  $('point-environment').innerHTML=`<div class="env-section"><div class="eyebrow">SELECTED LOCATION / MODEL</div><p>${point.lat.toFixed(3)}°, ${point.lon.toFixed(3)}°</p><dl class="env-metrics">${Object.entries(FIELDS).map(([key,f])=>metric(f.label,number(s.values[key],key==='dustOpticalDepth'?2:1)+' '+f.unit)).join('')}</dl><p class="env-note">Nearest model sample: ${s.gridLat.toFixed(2)}°, ${s.gridLon.toFixed(0)}° · ${s.offsetKm.toFixed(0)} km from this point. This is coarse climate context, not measured local weather.</p><p class="env-note">Pressure is ${(s.values.surfacePressurePa/101325*100).toFixed(2)}% of Earth sea-level reference pressure; this does not imply breathability.</p></div>`;
 }
 function renderStations(){
  if(!observations)return;const meda=observations.stations.find(s=>s.id==='meda'),rems=observations.stations.find(s=>s.id==='rems'),r=rems.records[remIndex];
  const dist=s=>point?` · ${distance(point,s).toFixed(0)} km to landing reference`:'';
  $('station-observations').innerHTML=`<article class="station-card"><h3>${esc(meda.name)}</h3><span class="data-badge">ARCHIVE · PDS</span><p>${meda.start.slice(0,10)} → ${meda.end.slice(0,10)} · sol ${meda.sol}<br>${ageDays(meda.end)} days old${dist(meda)}</p><dl class="env-metrics">${metric('Sensor 1 local air min / max',number(meda.airSensor1C.min)+' / '+number(meda.airSensor1C.max)+' °C')}${metric('Pressure mean',number(meda.pressurePa.mean)+' Pa')}${metric('Pressure min / max',number(meda.pressurePa.min)+' / '+number(meda.pressurePa.max)+' Pa')}${metric('Wind','No data for this sol')}</dl><p class="env-note">${meda.airSensor1C.count.toLocaleString('en')} temperature samples; ${meda.pressurePa.count.toLocaleString('en')} pressure samples. ${esc(meda.quality)}</p><p>${link(meda.sources[1],'ATS label')+' · '+link(meda.sources[3],'Pressure label')}</p><button id="focus-meda" class="env-button">Go to Jezero reference</button></article>
  <article class="station-card"><h3>${esc(rems.name)}</h3><span class="data-badge">ARCHIVE · OUTREACH</span><label class="env-label">REPORTED SOL<select id="rems-sol">${rems.records.map((v,i)=>`<option value="${i}" ${i===remIndex?'selected':''}>${v.date} · sol ${v.sol}</option>`).join('')}</select></label><p>${ageDays(r.date)} days old${dist(rems)}</p><dl class="env-metrics">${metric('Air min / max',number(r.airMinC)+' / '+number(r.airMaxC)+' °C')}${metric('Ground min / max',number(r.groundMinC)+' / '+number(r.groundMaxC)+' °C')}${metric('Pressure',number(r.pressurePa)+' Pa')}${metric('Wind',r.windSpeedMs==null?'No data':number(r.windSpeedMs)+' m/s')}${metric('UV category',r.uv??'No data')}${metric('Reported sky',r.condition??'No data')}</dl><p class="env-note">${esc(rems.quality)}</p><p>${link(rems.source,'NASA / CAB source')}</p><button id="focus-rems" class="env-button">Go to Gale reference</button></article><p class="env-note">Source files retrieved ${esc((observations.retrievedOn??observations.retrievedAt).slice(0,10))}. Retrieval date is not measurement date.</p>`;
  $('focus-meda').onclick=()=>callbacks.select({...meda,name:'Jezero landing reference'});$('focus-rems').onclick=()=>callbacks.select({...rems,name:'Gale landing reference'});$('rems-sol').onchange=e=>{remIndex=+e.target.value;renderStations();};
 }
 function renderRoute(){
  report=null;$('route-climate-export').disabled=true;if(!start||!end){$('route-climate-result').textContent='Set a start and destination.';return;}
  try{
   const km=distance(start,end),speed=+$('eva-speed').value,autonomy=+$('eva-autonomy').value,reserve=+$('eva-reserve').value,stops=+$('eva-stops').value;
   if([$('eva-speed'),$('eva-autonomy'),$('eva-reserve'),$('eva-stops')].some(el=>el.value.trim()===''||!el.checkValidity()))throw Error('Enter valid time-budget assumptions.');
   const budget=timeBudget(km,speed,autonomy,reserve,$('eva-return').checked,stops),climate=model?routeEnvironment(model,start,end):null;
   report={start,end,distanceKm:km,timeBudget:budget,climate,operationalSafety:'unknown',unknowns:['Current local weather','Dust storms','Ionising radiation','Slopes and obstacles','Oxygen / power consumption','Water and shelter','Communications']};
   $('route-climate-result').innerHTML=`<p class="env-warning">${budget.withinEnteredBudget?'Within entered time budget only':'Exceeds entered time budget'} · safety NOT determined</p><dl class="env-metrics">${metric('One-way distance',km.toFixed(2)+' km')}${metric('Planned time',budget.plannedHours.toFixed(2)+' h')}${metric('Time after reserve',budget.usableHours.toFixed(2)+' h')}${metric('Budget margin',budget.marginHours.toFixed(2)+' h')}</dl>${climate?`<p>MODEL · Ls ${climate.solarLongitude}° · ${climate.localSolarHour}:00 local at each point · ${climate.gridCells} distinct grid cells</p><dl class="env-metrics">${Object.entries(FIELDS).map(([k,f])=>metric(f.label,number(climate.ranges[k].min)+' — '+number(climate.ranges[k].max)+' '+f.unit)).join('')}</dl>`:'<p>No climate model available.</p>'}<p class="env-note">Candidate great-circle route, not terrain-following or obstacle avoidance. Model ranges are coarse scenario samples, not conditions at the planned traversal time. No safe/unsafe terrain score is inferred.</p>`;
   $('route-climate-export').disabled=false;
  }catch(e){$('route-climate-result').textContent=e.message;}
 }
 async function load(){const token=++epoch;model=null;$('show-climate').disabled=true;$('climate-retry').hidden=true;$('climate-status').textContent='Loading seasonal model…';renderPoint();renderRoute();const ls=$('climate-season').value,hour=$('climate-hour').value,key=ls+'-'+hour;
  try{if(!cache.has(key))cache.set(key,fetch(`./data/climate-${key}.json`).then(r=>{if(!r.ok)throw Error('Climate snapshot unavailable');return r.json();}).then(validateClimate).catch(e=>{cache.delete(key);throw e;}));const data=await cache.get(key);if(token!==epoch)return;model=data;$('show-climate').disabled=false;$('climate-status').textContent=`MCD 6.2 · Ls ${ls}° · ${hour}:00 local · MODEL / not live`;$('climate-source').innerHTML=link(model.source,'MCD scenario query')+'<br>Retrieved '+esc(model.retrievedAt.slice(0,10));renderPoint();renderRoute();if(mapped)draw();}
  catch(e){if(token!==epoch)return;$('climate-status').textContent=e.message+' · displayed map may be the previous scenario';$('climate-retry').hidden=false;}
 }
 $('climate-season').onchange=load;$('climate-hour').onchange=load;$('climate-retry').onclick=load;$('show-climate').onclick=draw;$('climate-field').onchange=e=>{selectedField=e.target.value;legend();if(mapped)draw();};$('point-export').onclick=()=>download(pointReport(),'mars-point-environment.json');$('route-climate-export').onclick=()=>{if(report)download(report,'mars-route-environment.json');};
 for(const id of ['eva-speed','eva-autonomy','eva-reserve','eva-stops','eva-return'])$(id).addEventListener('input',renderRoute);
 document.querySelectorAll('input[name="layer"]').forEach(input=>input.addEventListener('change',()=>{mapped=false;}));
 fetch('./data/observations.json').then(r=>{if(!r.ok)throw Error('Archive snapshot unavailable');return r.json();}).then(data=>{observations=data;renderStations();}).catch(e=>{$('station-observations').textContent=e.message;});
 legend();load();
 return {select(p){point=p;renderPoint();renderStations();},route(a,b){start=a;end=b;renderRoute();},report(){return report;}};
}

